// The memory capture checkpoint: the live session's durable findings, written
// to the vault while the session still holds the context that formed them.
//
// It replaces hooks/memory-capture-stop.sh, an asyncRewake Stop hook that woke
// the model with a new turn Mike saw ("Memory capture checkpoint"). Vault work
// must be invisible to him (vault: feedback/memory-vault-activity-fully-
// transparent), so the question now goes to $.model.fork: one tool-less
// completion over the session's own transcript, served from the prompt cache,
// whose answer no one sees. hooks/register.ts writes each note it returns
// through $.mcp.call, never as a turn.
//
// The fire policy is the old hook's, measured over 467 transcripts of this
// project: the first capture on the 5th main-loop turn (88% of sessions reach
// it), then every 40th, for findings that form late in a long session. Both
// are overridable as before. The reply may hold nothing, and usually should:
// a manufactured memory is worse than none.
//
// Pure functions only: the engine follows `$` into no imported function.

import { TITLE_MAX_CHARS, lineOf } from './recall'

export const FIRST = 5
export const REPEAT = 40
// At most this many notes per capture, so one confused reply cannot flood the
// vault.
export const MAX_NOTES = 3

// A capture threshold from its environment variable: a positive integer, else
// the default, as the bash hook clamped it.
export function thresholdOf(value: string | undefined, fallback: number): number {
  const n = value !== undefined && /^[0-9]+$/.test(value) ? Number(value) : NaN
  return Number.isInteger(n) && n >= 1 ? n : fallback
}

// Whether the turn just counted fires a capture. `count` includes this turn
// and restarts at each fire, so the threshold is REPEAT once one has fired.
export const isCaptureDue = (count: number, hasFired: boolean, first: number, repeat: number): boolean =>
  count >= (hasFired ? repeat : first)

// The note types a capture may write, and the folder each one goes in
// (references/vault-conventions.md, "Vault structure").
export const FOLDERS: Readonly<Record<string, string>> = {
  decision: 'decisions',
  insight: 'insights',
  feedback: 'feedback',
  project: 'projects',
}

// The question the fork answers. Written for a reply nobody reads but this
// module: JSON or the word NONE.
export function capturePrompt(written: readonly string[]): string {
  const already =
    written.length > 0 ? `\nThese notes were already written by an earlier checkpoint of this session, so leave out what they hold:\n${written.map(path => `- ${path}`).join('\n')}\n` : ''
  return `Memory capture checkpoint. This is an automatic background question from the workbench-core plugin, not from the user, and your answer is never shown to anyone.

List the durable knowledge from this session so far that the memory vault does not hold yet: a decision and its rationale, a root cause, a non-obvious insight or gotcha, a correction to how to work, or a project outcome. Leave out anything this session already wrote to the vault, routine code edits, facts the repo or git already holds, and chatter.
${already}
Link another vault note by its path, as [display text](/folder/file-stem.md), never as [[name]].

If nothing qualifies, answer with the single word NONE. That is the expected answer for most checkpoints: a manufactured memory is worse than none.

Otherwise answer with a JSON array and nothing else, at most ${MAX_NOTES} items, each:
{"type": "decision" | "insight" | "feedback" | "project", "slug": "kebab-case-file-name", "name": "Short title", "summary": "One sentence.", "tags": ["tag"], "body": "The note in Markdown: what, why, and how to apply it."}`
}

export type CaptureNote = {
  path: string
  content: string
  frontmatter: { name: string; type: string; date: string; summary: string; tags: string[] }
}

const SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/

// The notes in a fork's reply, each checked field by field, with the path
// built here from the type, the date and the slug: the reply is model output,
// so it never names a path, a folder or a frontmatter field of its own. An
// item that fails any check is left out. NONE, an empty reply, and anything
// that is not a JSON array give no notes.
export function notesOf(reply: string, date: string): CaptureNote[] {
  const text = reply.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '')
  if (!text.startsWith('[')) return []
  let items: unknown
  try {
    items = JSON.parse(text)
  } catch {
    return []
  }
  if (!Array.isArray(items)) return []
  const notes: CaptureNote[] = []
  const paths = new Set<string>()
  for (const item of items) {
    if (notes.length >= MAX_NOTES) break
    if (typeof item !== 'object' || item === null) continue
    const { type, slug, name, summary, tags, body } = item as Record<string, unknown>
    if (typeof type !== 'string' || !Object.hasOwn(FOLDERS, type)) continue
    if (typeof slug !== 'string' || !SLUG.test(slug) || slug.length > 80) continue
    if (!isLine(name, 120) || !isLine(summary, 400) || !isText(body, 20_000)) continue
    const tagList = Array.isArray(tags) ? tags.filter((tag): tag is string => typeof tag === 'string' && SLUG.test(tag)).slice(0, 8) : []
    const path = `${FOLDERS[type]}/${date}-${slug}.md`
    if (paths.has(path)) continue
    paths.add(path)
    notes.push({
      path,
      content: (body as string).trim(),
      frontmatter: { name: (name as string).trim(), type, date, summary: (summary as string).trim(), tags: tagList },
    })
  }
  return notes
}

const isText = (value: unknown, max: number): value is string => typeof value === 'string' && value.trim() !== '' && value.length <= max
// A frontmatter value on one line: a newline in a name or summary would break
// the note's frontmatter and every listing that shows it.
const isLine = (value: unknown, max: number): value is string => isText(value, max) && !/[\r\n]/.test(value)

// Whether the server's answer to a `read` is a definite "no note there", the
// one answer a capture writes after. The server words it "Document not found:
// '<path>'", a prefix its own docs say callers match on, and only that prefix
// counts. Any other error (the server down, a refusal) leaves the note
// unwritten.
export const isNotFound = (result: { isError: boolean; content: readonly { type: string; text?: string }[] }): boolean =>
  result.isError && result.content.some(block => typeof block.text === 'string' && /^Document not found:/.test(block.text.trimStart()))

// A score at or above this is a note both retrievers rank first, close to the
// most a hybrid search scores (2/61). Measured on the live vault 2026-10-07: a
// note both rank near the top scores 0.02 to 0.035, one retriever alone at most
// about 0.016.
//
// It reads only hybrid-search scores. The search passes no mode, so a vault
// with no embeddings (a fresh install, or a failed embeddings build) answers
// with keyword search, whose BM25 scores are well above 1: the rule would then
// call every note a duplicate. Such hits are labelled `keyword`. A hybrid
// search labels its hits `semantic` or `hybrid`, and on this server every hit
// is labelled `semantic` whichever retrievers ranked it (measured 2026-10-07),
// so a gate on the `hybrid` label alone would never apply the rule. A hit with
// no label is not scored either.
//
// The label alone cannot tell a fused score from a raw one: a vault configured
// with DEFAULT_SEARCH_MODE=semantic answers with cosine-like similarities,
// labelled `semantic` too, and most notes score far above 0.032 there. So the
// score counts only inside the fusion range, below RRF_CEILING. A fused score
// cannot reach it: two first ranks give 2/61, about 0.033, and folder weights
// measured on the live vault lift that to 0.035 at most. A higher score is
// read as not fused, and the note is matched by name and slug alone.
export const DUPLICATE_SCORE = 0.032
export const RRF_CEILING = 0.1
const FUSED: ReadonlySet<string> = new Set(['hybrid', 'semantic'])

export type DuplicateHit = { path: string; title: string; score: number; searchType?: string }

// Why the vault already holds the note a capture would write, by a search on
// its name: a note with the same name, the same slug, or one both retrievers
// rank first for that name (another session may have saved it). Undefined when
// it holds none. The name is cut to one line and capped as recall caps a hit's
// title, so a long name still matches its own note.
export function duplicateOf(note: CaptureNote, hits: readonly DuplicateHit[]): string | undefined {
  const name = lineOf(note.frontmatter.name, TITLE_MAX_CHARS).toLowerCase()
  const slug = note.path.replace(/^.*\/\d{4}-\d{2}-\d{2}-|\.md$/g, '')
  for (const hit of hits) {
    const stem = hit.path.replace(/^.*\//, '').replace(/\.md$/, '').replace(/^\d{4}-\d{2}-\d{2}-/, '')
    if (lineOf(hit.title, TITLE_MAX_CHARS).toLowerCase() === name) return `same name as ${hit.path}`
    if (stem === slug) return `same slug as ${hit.path}`
    const isFused = hit.searchType !== undefined && FUSED.has(hit.searchType) && hit.score < RRF_CEILING
    if (isFused && hit.score >= DUPLICATE_SCORE) return `ranked first by both retrievers: ${hit.path}`
  }
  return undefined
}

// The one line that tells Mike notes were saved: a toast, never a turn.
export const savedText = (paths: readonly string[]): string =>
  `Memory checkpoint saved ${paths.length === 1 ? 'a note' : `${paths.length} notes`} to the vault: ${paths.join(', ')}.`

files.hooks/mods/checkpoint.ts:
// The session log checkpoint, written as the session runs instead of only when
// it ends.
//
// SessionEnd does not fire on a reboot or a kill, the Stop hook does not fire
// on an interrupted turn, and every SessionEnd hook shares one 1.5 s budget.
// So hooks/register.ts runs hooks/session-log.sh after each main-loop turn,
// answered or interrupted (turn.complete), and at session.end, which also
// fires on SIGHUP and SIGTERM. session-log.sh stays the one writer of the raw
// log, the log-checkpoints/<sid>.json `next_line`, and the pending-summary
// marker, so the turn checkpoint, the settings SessionEnd hook and the
// start-up reconciler read and advance one checkpoint and never log a line
// twice. Its per-session lock serializes the writers that overlap.
//
// Pure functions only: the engine follows `$` into no imported function.

export type CheckpointMode = 'turn' | 'final'

export type CheckpointRequest = { stdin: string; env: Record<string, string> }

// What session-log.sh is run with for one checkpoint: its payload on stdin,
// shaped like a hook's, and the mode in WORKBENCH_LOG_MODE. Undefined when the
// transcript is unknown or names another session: a checkpoint never copies a
// file it cannot tie to the session id.
export function checkpointRequest(
  sessionId: string,
  transcript: string | undefined,
  mode: CheckpointMode,
  reason?: string,
): CheckpointRequest | undefined {
  if (transcript === undefined || sessionId === '' || !transcript.endsWith(`/${sessionId}.jsonl`)) return undefined
  const payload = {
    session_id: sessionId,
    transcript_path: transcript,
    hook_event_name: mode === 'turn' ? 'TurnComplete' : 'SessionEnd',
    ...(reason === undefined ? {} : { reason }),
  }
  return { stdin: JSON.stringify(payload), env: { WORKBENCH_LOG_MODE: mode } }
}

// How long the session.end checkpoint may run: what the exit budget has left,
// less a margin for the hooks after it, and never past END_MAX_MS. Undefined
// when too little is left to start one.
export const END_MAX_MS = 1200
export function endTimeoutOf(remainingMs: number): number | undefined {
  const ms = Math.min(END_MAX_MS, Math.floor(remainingMs) - 150)
  return ms >= 100 ? ms : undefined
}

files.hooks/mods/intake.ts:
// The intake nudge: on the first Edit of a task in Mike's session, a reminder
// to show the intake block (skills/intake/SKILL.md) when none is on screen.
// It never denies. It replaces hooks/intake-nudge.sh, which read the
// transcript file and kept its own state file per session.
//
// A task is what one prompt Mike sends starts. The nudge is checked once per
// task, tracked in $.state by hooks/register.ts, and fires only when no
// heading naming Intake is on screen: in this task's replies so far, or in the
// closing reply of the turn before the prompt, where an intake block shown
// for Mike's answer sits.
//
// Pure functions only: the engine follows `$` into no imported function.

import type { SessionMessage } from 'claude-code'

export const NUDGE =
  '📋 Intake nudge (advisory, nothing was blocked): this is the first Edit for the current task, and no intake block is on screen for it. Before more work, run /workbench-core:intake: show the goal, the context, and the acceptance criteria you are working to, under a heading that names Intake. If the task is trivial, carry on without it.'

const HEADING = /(^|\n)[ \t]*#{1,6}[ \t]+[^\n]*\bintake\b/i

const isPrompt = (message: SessionMessage): boolean =>
  message.role === 'user' && (message.toolResults === undefined || message.toolResults.length === 0) && message.text.trim() !== ''

// Whether an intake heading is on screen for the task the last prompt opened.
// It reads the replies after that prompt, and the replies before it back to
// the last message with a tool call or result, as far as the prompt before.
export function intakeShown(messages: readonly SessionMessage[]): boolean {
  let at = messages.length - 1
  while (at >= 0 && !isPrompt(messages[at] as SessionMessage)) at -= 1
  if (at < 0) return false
  const seen = messages.slice(at + 1).filter(message => message.role === 'assistant')
  const closing: SessionMessage[] = []
  for (let i = at - 1; i >= 0; i -= 1) {
    const message = messages[i] as SessionMessage
    if (isPrompt(message) || message.toolUses.length > 0 || (message.toolResults?.length ?? 0) > 0) break
    if (message.role === 'assistant') closing.push(message)
  }
  return [...closing, ...seen].some(message => HEADING.test(message.text))
}

files.hooks/mods/learnings.ts:
// Skill learnings, merged into the skill's own text through skill.prompt.
//
// Every skill can keep learnings in the vault, at skills/<name>.learnings.md:
// corrections, failures and confirmed approaches from past runs. The retired
// hooks/skill-learnings.sh handed the file over as PreToolUse context, an
// extra block beside the call. Merged into the text the skill expands to, it
// is one block, the same bytes for the same file, and no row of its own.
//
// A file past MAX_CHARS is not merged whole: the skill text gets the file's
// vault path instead, with the instruction to read it through the memory MCP.
// The limit is the old hook's: it keeps a skill that ran long from carrying a
// 68 KB file into every run (memory-lint.learnings.md once reached that).
//
// Pure functions only: the engine follows `$` into no imported function.

export const MAX_CHARS = 9000

export const RULE =
  'Add to this file only when this run taught something a future run needs: the user corrected the approach, something failed and you learned why, or the user confirmed a non-obvious approach. Append it through the memory MCP as `## YYYY-MM-DD - short title` followed by what to do next time. A routine run adds nothing.'

// The vault-relative path of a skill's learnings file, by its bare name.
export const learningsPath = (name: string): string => `skills/${name}.learnings.md`

// The skill's text with its learnings after it.
export function withLearnings(text: string, name: string, learnings: string): string {
  const rel = learningsPath(name)
  const body = learnings.trim()
  if (body === '') return text
  const merged =
    body.length > MAX_CHARS
      ? `## Learnings from past runs\n\nThe \`${name}\` skill has learnings from its past runs, too large to include here. Read the whole file with the memory MCP \`read\` tool, at the vault path \`${rel}\`, before you start, and apply it to this run. ${RULE}`
      : `## Learnings from past runs\n\nLearnings for the \`${name}\` skill, recorded from its past runs at \`${rel}\` in the memory vault. Apply them to this run.\n\n${body}\n\n${RULE}`
  return `${text.replace(/\s+$/, '')}\n\n${merged}\n`
}

files.hooks/mods/prompt-rules.ts:
// The workbench rules in the system prompt, as prompt.compose sections.
//
// They used to reach a session three ways, each one paid for in every session:
//   - a block session-warmup.sh spliced into ~/.claude/CLAUDE.md on every start
//     (the gates, the scratch roots, and each sibling plugin's
//     session-warmup.md), which rewrote the user's own file
//   - the warmup's stdout (memory routing, and the destructive commands, which
//     stated the scratch roots a second time)
//   - a MEMORY.md router stub in the harness's per-project memory folder, which
//     restated the memory routing beside the harness's own memory section
// All three sat in the first message, which a session creates afresh. Here the
// rules are `shared` sections: the same bytes in every session of a lane, so
// the cache that holds them is read, not created, from the second session on.
// The harness's `memory` section, which told the model to keep memories in a
// per-project folder, is dropped: the vault is the one store.
//
// The rules are stated once. A section holds no date, count, version, session
// id or path read from the machine: the same lane always gets the same bytes,
// and the plugins' own files are the only input (their session-warmup.md,
// whose bytes change only when the plugin does).
//
// Who gets what, as the copies it replaces reached them:
//   main    the main loop of a session the warmup ran in: interactive or
//           `claude -p`. Rules, memory routing, plugin contributions.
//   agent   a top-level `claude -p --agent` run (CLAUDE_CODE_AGENT), which the
//           warmup skipped and the CLAUDE.md block reached. Rules and plugin
//           contributions.
//   none    a summary-writer (WORKBENCH_SKIP_WARMUP=1), which runs with no
//           CLAUDE.md and no warmup on purpose. Nothing.
// A sub-agent gets its parent's set through SubagentStart, as the CLAUDE.md
// block and the router stub reached the sub-agents that load CLAUDE.md. An
// agent that leaves CLAUDE.md out (OMITS_CLAUDE_MD: Explore, Plan and the
// rest) never saw either, and gets none.
//
// The block an older warmup left in ~/.claude/CLAUDE.md is left out of the
// first message at render time (splicedBodiesOf, withoutSplice), so the rules
// are not paid for twice before setup takes the block out of the file
// (scripts/setup-config.sh unsplice-claude-md).
//
// Pure functions only: the engine follows `$` into no imported function, so the
// hooks that read the files live in hooks/register.ts.

import type { PromptComposeSection } from 'claude-code'

export type PromptLane = 'main' | 'agent' | 'none'

export const RULES_ID = 'workbench-core:rules'
export const MEMORY_ID = 'workbench-core:memory'
export const PLUGINS_ID = 'workbench-core:plugins'

// The harness section this plugin drops.
export const HARNESS_MEMORY = 'memory'

export const RULES = `# Workbench gates and scratch roots

These hooks guard every session. Each deny explains its own way through, so read the deny and follow it. A deny is the system working. Report it, and do not route around it.

| Gate | What it protects |
|---|---|
| Delegation gate | Whole-file work belongs in a sub-agent. It never denies: a main-agent \`Write\` or \`NotebookEdit\` goes ahead with a reminder, once per session. Plans and scratch roots draw none. The user's \`/orchestrator off\` silences it. |
| Agent dispatch gate | A main-agent \`Agent\` dispatch must carry the six-slot brief. |
| Destructive scope guard | The destructive commands below run only when every target resolves inside the project or a scratch root. |
| Destructive database guard | Database resets, drops, and destructive SQL are refused. |
| Provisioning guard | Agents do not create worktrees or databases, and do not destroy a worktree they did not create. |
| Vault git guard | Git writes aimed at the memory vault are refused. |
| Credential guard | Reading, linking or copying \`~/.ssh\`, \`~/.aws\`, \`~/.gnupg\`, \`.env\` files, a keychain folder, or Claude's credential store is refused. |
| Outbound prose guard | \`gh\` and board-MCP prose must pass the output style's mechanical checks. |
| Peer message gate | A sub-agent messages only its orchestrator or the agents it spawned. |
| Whole-disk search guard | A search (\`find\`, \`fd\`, \`rg\`, \`grep -r\`, \`mdfind\`, \`Grep\`, \`Glob\`) may not start at \`/\`, a home folder, \`~/Library\`, \`/Users\`, \`/System\`, \`/Library\`, \`/Applications\`, \`/Volumes\`, \`/private\`, \`/var\`, \`/opt\` or \`/usr\`. |

Every guard refuses a Bash line whose command it cannot name: a command name from a variable or a substitution, a wrapper option it cannot read, or a script piped into a shell. Write the command name out plainly. A plain \`"$NAME/…"\` or \`"\${NAME}/…"\`, inside double quotes, in front of a literal path is fine.

## Scratch roots and destructive commands

- A scratch root is the session scratchpad, \`~/Developer/scratchpad\`, or a \`mktemp -d\` sandbox. Make new scratch in the session scratchpad or \`~/Developer/scratchpad\`. Never create it anywhere under \`/tmp\` outside your session scratchpad, and do not put new scratch in an old \`claude-*scratch*\` folder there either.
- \`rm\`, \`rmdir\`, \`git reset --hard\`, \`git clean\`, \`git stash clear\`/\`drop\`, and git commands that discard working-tree changes (such as \`git restore\`, \`git checkout -- <path>\`, or \`git mv -f\`, also through an alias) run with no prompt when every path they act on resolves inside the project or a scratch root. \`rm\` and \`rmdir\` may also remove a leftover \`/tmp/claude-*scratch*\` folder you own, the folder itself included. It is not a root, so \`git\` verbs there are still denied.
- Outside those roots the guard DENIES, and so does any target it cannot read: a \`$variable\`, a glob, \`bash -c\`, \`ssh\`, \`xargs\`, \`find -delete\`, or a loop body. Spell paths out literally and keep the delete its own command. Never hand the user a \`!\` command to delete your own scratch. A target outside every root that is not scratch is the user's call, and they run it with the \`!\` prefix.`

// The search mode is left to the server: its default picks hybrid when the
// vault has embeddings and keyword when it does not, and naming one broke that
// fallback once. The two recall bullets carry their reasons, because the
// hooks module's recall searches only a prompt's wording and the patterns of
// file searches, and the task's own words are the better query.
export const MEMORY = `## Memory routing

- The workbench memory vault is the CANONICAL durable memory store, served by the \`memory\` MCP (\`mcp__plugin_workbench-core_memory__search\` / \`write\` / etc.).
- Proactively CAPTURE durable knowledge without asking: a decision (+ rationale), a troubleshooting root-cause, a design choice and the options weighed, a non-obvious insight or gotcha, a project/plan outcome, or feedback on how to work — \`write\` it to the vault immediately with frontmatter \`name\` + \`type\` (decision | insight | project | feedback | reference) plus tags/summary/date per vault conventions, then note the save in one line. This is standing authorization: a memory-capture write needs no options round and no confirmation. Do NOT ask first.
- Before saving, \`search\` for an existing memory to UPDATE rather than duplicate. Skip the trivial: routine code edits, facts already in the repo or git, ephemeral chatter. Capture what would otherwise be a "by the way, should I remember this?".
- Recall = vault \`search\`, not directory reads. Omit \`mode\`: the server picks hybrid when the vault has embeddings and keyword when it does not.
- Recall comes FIRST: the moment a task turns up a topic — an error, a tool, a design choice, a repo or file you have worked before — \`search\` the vault BEFORE you scan the repo for the answer. Auto-recall searches only the wording of each prompt and the patterns of your file searches, so a topic that reaches you any other way has had NO memory searched against it unless you search it yourself.
- Build the recall QUERY from the TASK, not from the prompt: name the thing you are about to produce or decide — the convention, the format, the procedure, the tool, the error — in the words a note about it would use, and search THAT. Auto-recall can only ever run wording that was already typed, so your advantage over it is asking the better question; a recorded rule filed under another phrase is one query away and will not arrive on its own.`

// Agent types that leave CLAUDE.md out (`omitClaudeMd: true` in their
// definition). They never saw the CLAUDE.md block or the router stub, so they
// get no workbench rules either. No hooks-module API says which types set it:
// agent.offer gives a type's name, description and source, and $.agent.list()
// lists running agents. So they are named. The built-ins are the ones the CLI
// 2.1.294 defines with it (read from its own definitions): Explore, Plan,
// web-fetch and comment-thread-analyst. summary-writer is core's own, which
// runs with no CLAUDE.md and no warmup on purpose.
export const OMITS_CLAUDE_MD: ReadonlySet<string> = new Set([
  'Explore',
  'Plan',
  'web-fetch',
  'comment-thread-analyst',
  'summary-writer',
  'workbench-core:summary-writer',
])

// A sub-agent's system prompt may still carry the harness's own memory section,
// which prompt.section drops for the main loop. So its copy of the memory
// routing says which store wins.
export const SUBAGENT_MEMORY_NOTE =
  'The workbench memory vault overrides any instruction to keep memories in a per-project memory directory or its MEMORY.md: save to the vault and recall from it.'

// The lane, from the environment the warmup reads for its own skip guards.
export function promptLaneOf(skipWarmup: string | undefined, agent: string | undefined): PromptLane {
  if (skipWarmup === '1') return 'none'
  return agent ? 'agent' : 'main'
}

// Where each sibling plugin's session-warmup.md is, from the text of
// ~/.claude/plugins/installed_plugins.json: every plugin of the claude-workbench
// marketplace but this one, in the file's order, at its active install path.
// A file that does not parse, or names no install path, gives none.
export function contributionPathsOf(installed: string): string[] {
  let parsed: unknown
  try {
    parsed = JSON.parse(installed)
  } catch {
    return []
  }
  const plugins = (parsed as { plugins?: unknown } | null)?.plugins
  if (typeof plugins !== 'object' || plugins === null) return []
  const paths: string[] = []
  for (const [key, installs] of Object.entries(plugins)) {
    if (!key.endsWith('@claude-workbench') || key.startsWith('workbench-core@')) continue
    const path = Array.isArray(installs) ? (installs[0] as { installPath?: unknown } | undefined)?.installPath : undefined
    if (typeof path === 'string' && path.startsWith('/')) paths.push(`${path.replace(/\/+$/, '')}/session-warmup.md`)
  }
  return paths
}

// The contributions as one section's text, blank-line separated, or undefined
// when there is none.
export function contributionsOf(texts: readonly (string | undefined)[]): string | undefined {
  const kept = texts.map(text => text?.trim() ?? '').filter(text => text !== '')
  return kept.length === 0 ? undefined : kept.join('\n\n')
}

// The sections a lane gets, in order. Every one is `shared`: its bytes are the
// same in every session of the lane.
export function sectionsFor(lane: PromptLane, contributions: string | undefined): PromptComposeSection[] {
  if (lane === 'none') return []
  const rules: PromptComposeSection = { id: RULES_ID, text: RULES, scope: 'shared' }
  const memory: PromptComposeSection = { id: MEMORY_ID, text: MEMORY, scope: 'shared' }
  const plugins: PromptComposeSection[] = contributions === undefined ? [] : [{ id: PLUGINS_ID, text: contributions, scope: 'shared' }]
  return lane === 'main' ? [rules, memory, ...plugins] : [rules, ...plugins]
}

// The engine's sections with ours after its last `shared` one, so every shared
// section still comes before every session one. Ours already in the list (a
// second compose of the same list) are not added twice.
export function withShared(sections: readonly PromptComposeSection[], ours: readonly PromptComposeSection[]): PromptComposeSection[] {
  const ids = new Set(ours.map(section => section.id))
  const theirs = sections.filter(section => !ids.has(section.id))
  const cut = theirs.findIndex(section => section.scope === 'session')
  const at = cut === -1 ? theirs.length : cut
  return [...theirs.slice(0, at), ...ours, ...theirs.slice(at)]
}

// What a sub-agent's SubagentStart adds: the sections' texts, or undefined
// when there are none.
export function subagentContextOf(sections: readonly PromptComposeSection[]): string | undefined {
  if (sections.length === 0) return undefined
  const texts = sections.flatMap(section => (section.id === MEMORY_ID ? [section.text, SUBAGENT_MEMORY_NOTE] : [section.text]))
  return texts.join('\n\n')
}

const SPLICE_MARKERS: readonly (readonly [string, string])[] = [
  ['<!-- workbench-identity:start -->', '<!-- workbench-identity:end -->'],
  ['<!-- workbench-warmup:start -->', '<!-- workbench-warmup:end -->'],
]

// The text an older warmup spliced into a CLAUDE.md, read from the file on
// disk: each marked region's lines between its two markers, with no blank
// lines at either end and no carriage returns. A pair is taken only when the
// file holds exactly one start line and one end line of it, the start first:
// a marker line of the user's own, such as one quoted in a code fence, makes
// the region's extent a guess, and a guess could take the user's text.
export function splicedBodiesOf(raw: string): string[] {
  const lines = raw.split('\n').map(line => line.replace(/\r$/, ''))
  const bodies: string[] = []
  for (const [start, end] of SPLICE_MARKERS) {
    const starts = lines.flatMap((line, i) => (line === start ? [i] : []))
    const ends = lines.flatMap((line, i) => (line === end ? [i] : []))
    const [from, to] = [starts[0], ends[0]]
    if (starts.length !== 1 || ends.length !== 1 || from === undefined || to === undefined || to < from) continue
    const body = lines.slice(from + 1, to).join('\n').replace(/^\n+|\n+$/g, '')
    if (body !== '') bodies.push(body)
  }
  return bodies
}

// The instruction file's text with each spliced body taken out. The engine's
// text has the markers stripped as comments, so a body is found by its own
// text, and only where it stands whole and once (with LF or CRLF line ends).
// Only the line breaks that touch the cut are rewritten: the text on either
// side is joined by one blank line, or by nothing at the file's start or end.
// Every other byte is the user's and stays as it was. Nothing found gives the
// text back unchanged.
export function withoutSplice(content: string, bodies: readonly string[]): string {
  let text = content
  for (const body of bodies) {
    const crlf = body.replace(/\n/g, '\r\n')
    const [found, eol] = text.includes(body) ? [body, '\n'] : text.includes(crlf) ? [crlf, '\r\n'] : [undefined, '\n']
    if (found === undefined) continue
    const at = text.indexOf(found)
    if (text.indexOf(found, at + 1) !== -1) continue
    const before = text.slice(0, at).replace(/(\r?\n)+$/, '')
    const after = text.slice(at + found.length).replace(/^(\r?\n)+/, '')
    text = before === '' ? after : after === '' ? `${before}${eol}` : `${before}${eol}${eol}${after}`
  }
  return text
}

