// The question rule: every question to Mike goes through AskUserQuestion, with
// its context written in prose immediately above the call.
//
// Mike reads replies in an 80x50 terminal. A question left in prose scrolls
// away, and a dialog with no context right above it cannot be answered without
// scrolling back. The output style states the rule (rule 4). hooks/register.ts
// enforces its two halves with the functions below:
//
//   classic.Stop             A reply that leaves a question in prose gets one
//                            correction turn: the stop is blocked with a reason
//                            that tells the model to re-ask through the tool.
//   tool.call                An AskUserQuestion call with no prose immediately
//   (AskUserQuestion)        before it, in the same message, is refused.
//
// Pure functions only: the engine follows `$` into no imported function.

export const REPROMPT_REASON =
  'Your reply leaves a question for Mike in prose. Ask it again through ' +
  'AskUserQuestion. Write the context the question needs in prose immediately ' +
  'above the call, in the same message, and do not repeat the rest of the ' +
  'reply. A question with no fixed choices still fits the tool, because the ' +
  'dialog always offers Other.'

export const REFUSAL_REASON =
  'AskUserQuestion was refused: no prose comes immediately before this call ' +
  'in the same message. Write the context Mike needs to answer first, in ' +
  'prose directly above the call, then call AskUserQuestion again. He reads ' +
  'in an 80x50 terminal, and a dialog with no context right above it cannot ' +
  'be answered without scrolling back.'

// The labels the classifier picks from. Each one names its meaning, because
// the classifier reads the labels and the text, and nothing else.
export const ASKS_USER = 'asks-the-user-to-answer-or-decide'
export const ASKS_NOTHING = 'asks-the-user-nothing-or-only-rhetorically'
export const LABELS = [ASKS_USER, ASKS_NOTHING] as const

// Phrases that ask without a question mark. They only decide whether the
// classifier runs. The classifier decides whether the reply asks.
const REQUEST =
  /\b(let me know|tell me|do you want|would you like|should i|shall i|which (one|option)|your call|up to you|please (choose|pick|decide|confirm|advise))\b/i

// Text Mike did not get asked: fenced code, inline code, quoted lines, and
// double-quoted spans. A question inside them is shown, not asked. A fence
// left open runs to the end of the reply, as Markdown renders it.
export const proseOf = (reply: string): string =>
  reply
    .replace(/(```|~~~)[\s\S]*?(\1|$)/g, '')
    .replace(/`[^`\n]*`/g, '')
    .replace(/^ {0,3}>.*$/gm, '')
    .replace(/"[^"\n]*"|“[^”\n]*”/g, '')

export const hasCandidate = (prose: string): boolean => prose.includes('?') || REQUEST.test(prose)

// What the classifier reads: the reply's prose, its tail when it is long.
export const classifierText = (prose: string): string =>
  `The final message of an assistant's reply to its user:\n\n${prose.slice(-6000)}`

// The deterministic reading, used only when the classifier cannot answer: the
// last line of prose ends with a question mark.
export function endsOnQuestion(prose: string): boolean {
  const lines = prose.split('\n').map(line => line.trim()).filter(Boolean)
  return /\?[*_)\]\s]*$/.test(lines[lines.length - 1] ?? '')
}

type ApiBlock = { type: string; [field: string]: unknown }
type ApiMessage = { role: string; content: readonly ApiBlock[] }

// Whether prose comes immediately before the tool_use `id`, in the message
// that made it. Thinking blocks are skipped, because Mike never sees them.
// Undefined when no message holds the call, such as an AskUserQuestion another
// plugin raised through $.ui.ask.
export function hasContextBefore(messages: readonly ApiMessage[], id: string | undefined): boolean | undefined {
  if (id === undefined) return undefined
  for (let m = messages.length - 1; m >= 0; m--) {
    const content = messages[m]?.content ?? []
    const at = content.findIndex(block => block.type === 'tool_use' && block.id === id)
    if (at === -1) continue
    const before = content.slice(0, at).filter(block => !/thinking$/.test(block.type))
    const last = before[before.length - 1]
    return last?.type === 'text' && String(last.text ?? '').trim() !== ''
  }
  return undefined
}

files.hooks/mods/pending-summaries.ts:
// /process-pending-summaries: drain the pending session summaries, or summarize
// one session by id, with no model turn. scripts/process-pending-summaries.sh
// does the work through hooks/lib/summary-dispatch.sh, the helper the session
// warmup drains with, and prints one `result=` line. hooks/register.ts runs it
// and reports through a toast.
//
// It replaces the process-pending-summaries skill, which spent a model turn to
// run the same steps. It asks nothing: memory-vault work is never Mike's to
// answer (vault: feedback/memory-vault-activity-fully-transparent). The script
// redoes a summary only when the session's log is newer than it.
//
// Pure functions only: the engine follows `$` into no imported function.

export const NAME = 'process-pending-summaries'

export const REFUSAL = `/${NAME} runs only when Mike types it. A run from a plugin, a schedule or an agent dispatches nothing.`
export const USAGE = `Usage: /${NAME} [<session-id> [--overwrite]]`

export type Request = { sid?: string; overwrite: boolean }

// The command's arguments: nothing, or a session id and an optional
// --overwrite. Undefined for anything else.
export function requestOf(args: string): Request | undefined {
  const words = args.trim().split(/\s+/).filter(Boolean)
  const overwrite = words.includes('--overwrite')
  const rest = words.filter(word => word !== '--overwrite')
  if (rest.length > 1 || (rest.length === 0 && overwrite)) return undefined
  return { sid: rest[0], overwrite }
}

// The script's `result=` line, as fields. A run that printed none answers
// `{ result: 'failed' }`.
export function outcomeOf(stdout: string): Record<string, string> {
  const line = stdout.split('\n').find(row => row.startsWith('result=')) ?? 'result=failed'
  const fields: Record<string, string> = {}
  for (const pair of line.trim().split(' ')) {
    const at = pair.indexOf('=')
    if (at > 0) fields[pair.slice(0, at)] = pair.slice(at + 1)
  }
  return fields
}

// What the toast says for an outcome. The drain reports all four numbers: a
// run that dispatched none must not read like one that dispatched ten, and the
// dead count is the backlog's health signal.
export function reportOf(outcome: Record<string, string>, sid?: string): string {
  switch (outcome.result) {
    case 'none':
      return 'No pending session summaries.'
    case 'drained': {
      const { dispatched = '0', live = '0', dead = '0', total = '0' } = outcome
      const rerun = live !== '0' ? ` Run /${NAME} again to continue.` : ''
      return `Dispatched ${dispatched} background summary-writers. ${live} live markers remaining, ${dead} unprocessable (log and transcript both gone), ${total} total.${rerun}`
    }
    case 'invalid-id':
      return 'A session id holds only letters, digits and -.'
    case 'unrecoverable':
      return `Session ${sid} has no log and no transcript left, so it cannot be summarized.`
    case 'dispatched':
      return `A summary-writer is running for session ${sid}.`
    case 'current':
      return `The summary for session ${sid} is newer than its log, so it was kept.`
    case 'busy':
      return `A summary-writer is already summarizing session ${sid}.`
    case 'unavailable':
      return `Summaries cannot be dispatched: ${outcome.reason ?? 'a prerequisite'} is not available.`
    default:
      return 'The summary dispatch failed. See summary-dispatch-errors.log in the memory cache.'
  }
}

files.hooks/mods/request-meter.ts:
// The request meter: on the status line, the turns since session start and the
// latest API request's cost against the session's first API request's, as
// "T14 · $0.21/req · 3.4× first".
//
// A request is one main-loop API request: one `turn.step`, priced from the
// usage the API reported for that response alone. A turn of several tool calls
// makes several requests. A sub-agent's requests are its own, and are left
// out. T counts completed main-loop turns, from `turn.complete`.
//
// Each request is priced from its four token counts, for the model that
// answered. The figures are volatile, so they go to the status line and never
// into the system prompt, where a change would re-bill the cached prefix.
//
// Pure functions only: the engine follows `$` into no imported function, so the
// hooks that keep the figures and draw the line live in hooks/register.ts.

import type { TurnUsage } from 'claude-code'

import type { MeterState, RequestCost } from '../../types'

export const EMPTY: MeterState = { turns: 0, first: null, last: null }

// US dollars per million tokens: uncached input, output, and cache read, from
// the Anthropic list prices in the claude-api skill (cached 2026-09-25). A
// cache write is priced at 2 times input, the 1-hour TTL rate. The usage the
// engine reports does not split writes by TTL, but Claude Code's transcripts
// do. Across 400 of them, every main-loop write since 2026-09-01 was a 1-hour
// write, and priced that way a two-request probe matched the engine's own cost
// ledger to the cent. 0.5% of messages, from two desktop sessions in July and
// August, wrote 5-minute caches: there the write share reads up to 60% high.
const PRICES: Readonly<Record<string, readonly [input: number, output: number, cacheRead: number]>> = {
  'claude-fable-5-1': [10, 50, 0.25],
  'claude-mythos-5-1': [10, 50, 0.25],
  'claude-fable-5': [10, 50, 1],
  'claude-mythos-5': [10, 50, 1],
  'claude-opus-5-5': [4, 20, 0.2],
  'claude-opus-5': [5, 25, 0.5],
  'claude-opus-4-8': [5, 25, 0.5],
  'claude-opus-4-7': [5, 25, 0.5],
  'claude-opus-4-6': [5, 25, 0.5],
  'claude-sonnet-5-5': [2, 10, 0.2],
  'claude-sonnet-5': [2, 10, 0.2],
  'claude-sonnet-4-6': [3, 15, 0.3],
  'claude-haiku-4-5': [1, 5, 0.1],
}
const CACHE_WRITE = 2

// The family id in a model id as the API reports it: no provider prefix
// ("anthropic.", "us."), no context tag ("[1m]"), no date or version suffix.
export const familyOf = (model: string): string =>
  model
    .toLowerCase()
    .replace(/\[[^\]]*\]$/, '')
    .replace(/^.*?(?=claude-)/, '')
    .replace(/-v\d+(:\d+)?$/, '')
    .replace(/[-@]\d{8}$/, '')

// The request's cost in US dollars, or undefined for a model with no price,
// so an unknown model never shows a made-up figure.
export function priceOf(usage: TurnUsage): number | undefined {
  const price = PRICES[familyOf(usage.model)]
  if (price === undefined) return undefined
  const [input, output, cacheRead] = price
  const dollars =
    usage.input_tokens * input +
    usage.output_tokens * output +
    usage.cache_read_input_tokens * cacheRead +
    usage.cache_creation_input_tokens * input * CACHE_WRITE
  return dollars / 1e6
}

// Two significant digits or more, so a cheap request never reads as $0.00.
const usd = (dollars: number): string => `$${dollars.toFixed(dollars >= 0.1 ? 2 : dollars >= 0.01 ? 3 : 4)}`

// How the latest request compares with the first. The baseline is the
// session's true first request and never moves, so when it carries no usable
// figure the line says why instead of comparing against a later request.
function againstFirst(first: RequestCost, last: number): string {
  if (first.usd === null) return 'first unpriced'
  if (first.usd === 0) return 'first $0'
  return `${(last / first.usd).toFixed(1)}× first`
}

export function statusOf(state: MeterState): string {
  const turns = `T${state.turns}`
  const { first, last } = state
  if (first === null || last === null) return turns
  if (last.usd === null) return `${turns} · ${last.model} unpriced`
  return `${turns} · ${usd(last.usd)}/req · ${againstFirst(first, last.usd)}`
}

export const countTurn = (state: MeterState): MeterState => ({ ...state, turns: state.turns + 1 })

// A request the API answered. The first one ever seen becomes the baseline,
// priced or not. A step with no usage got no response, so the API reported no
// cost and it never reaches here.
export function countRequest(state: MeterState, usage: TurnUsage): MeterState {
  const cost: RequestCost = { model: usage.model, usd: priceOf(usage) ?? null }
  return { ...state, first: state.first ?? cost, last: cost }
}

files.hooks/mods/status-line.ts:
// The workbench's status line: the request meter, then the workbench facts
// Mike would otherwise learn only by reading a file or a model's reply.
//
//   T14 · $0.21/req · 3.4× first │ mem UP · orch on · rows 38/40 · learnings memory-lint 86 · 2 notices
//
//   mem        the memory server's health, from the identity-checked probe
//   orch       orchestrator mode for this session (/orchestrator)
//   rows       the rows the last reply takes at 80 columns, against the output
//              style's budget of about 40. A meter only: nothing re-prompts.
//   learnings  each skill whose learnings file is past the 30-entry limit,
//              which /workbench-core:compact-learnings compacts
//   notices    the warmup notices outstanding at session start (/notices)
//
// A fact not known yet is left out, so a line never shows a guess. Every figure
// here changes during a session, which is why it lives on the status line and
// never in the system prompt, where a change would re-bill the cached prefix.
//
// Pure functions only: the engine follows `$` into no imported function.

// The output style's reply budget: about 40 rows at 80 columns.
export const ROW_BUDGET = 40
export const COLUMNS = 80
// A learnings file past this many entries is due for compaction.
export const COMPACT_AT = 30

// The meter and the workbench facts, the meter first. Undefined when both are
// empty, which clears the line.
export function lineOf(meter: string | undefined, facts: readonly string[]): string | undefined {
  const workbench = facts.join(' · ')
  if (!meter) return workbench || undefined
  return workbench ? `${meter} │ ${workbench}` : meter
}

export type Facts = {
  memoryHealth?: string
  orchestratorOn?: boolean
  replyRows?: number
  learnings?: Readonly<Record<string, number>>
  notices?: readonly string[]
}

export function factsOf(facts: Facts): string[] {
  const out: string[] = []
  if (facts.memoryHealth) out.push(`mem ${facts.memoryHealth}`)
  if (facts.orchestratorOn !== undefined) out.push(`orch ${facts.orchestratorOn ? 'on' : 'off'}`)
  if (facts.replyRows !== undefined) out.push(`rows ${facts.replyRows}/${ROW_BUDGET}`)
  const due = Object.entries(facts.learnings ?? {}).sort(([a], [b]) => a.localeCompare(b))
  if (due.length > 0) out.push(`learnings ${due.map(([skill, count]) => `${skill} ${count}`).join(', ')}`)
  const notices = facts.notices?.length ?? 0
  if (notices > 0) out.push(notices === 1 ? '1 notice' : `${notices} notices`)
  return out
}

// The rows `text` takes at `columns`: each line one row, and a line longer than
// the width one more row for each width it runs past. Characters are counted
// by code point, so a wide character counts as one column: a floor, not a
// rendering.
export function rowsOf(text: string, columns = COLUMNS): number {
  if (text === '') return 0
  return text.split('\n').reduce((rows, line) => rows + Math.max(1, Math.ceil([...line].length / columns)), 0)
}

// The count scripts/learnings-count.sh printed, or undefined for anything
// that is not a whole number: no learnings file, or a script that failed.
export function countOf(stdout: string): number | undefined {
  const text = stdout.trim()
  return /^[0-9]+$/.test(text) ? Number(text) : undefined
}

// The skills due for compaction after `skill` was counted at `count`.
export function learningsAfter(learnings: Readonly<Record<string, number>>, skill: string, count: number | undefined): Record<string, number> {
  const { [skill]: _, ...rest } = learnings
  return count !== undefined && count > COMPACT_AT ? { ...rest, [skill]: count } : rest
}

// The bare skill name, as the learnings merge keys the learnings file:
// `workbench-core:memory-lint` and `memory-lint` are one skill. Undefined for
// a name that could leave the vault's skills folder.
export function skillNameOf(skill: string): string | undefined {
  const name = skill.slice(skill.lastIndexOf(':') + 1)
  return /^[A-Za-z0-9_-][A-Za-z0-9._-]*$/.test(name) ? name : undefined
}

// The notices in ~/.claude-workbench/warmup-notices.md: the text of each `## `
// heading, which is how session-warmup.sh opens every notice.
export const noticesOf = (markdown: string): string[] =>
  markdown
    .split('\n')
    .filter(line => line.startsWith('## '))
    .map(line => line.slice(3).trim())
    .filter(Boolean)

// The probe's word for the server's health, or undefined for output that is
// not one word.
export function healthOf(stdout: string): string | undefined {
  const word = stdout.trim()
  return /^[A-Z_]+$/.test(word) ? word : undefined
}

